<?php
declare(strict_types=1);require dirname(__DIR__,2).'/bootstrap.php';use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;Auth::requireAdmin();$pdo=Database::connection();$userId=(int)(Auth::user()['id']??0);if($_SERVER['REQUEST_METHOD']!=='POST'||!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Invalid security token.');}$action=(string)($_POST['action']??'');function auditD(PDO $p,int $r,int $u,string $a,array $d=[]):void{$p->prepare('INSERT INTO bdc_scoring_audit(round_id,user_id,action,details_json) VALUES(:r,:u,:a,:d)')->execute(['r'=>$r,'u'=>$u?:null,'a'=>$a,'d'=>json_encode($d)]);}try{if($action==='create_round'){$dance=in_array((string)($_POST['dance_style']??''),['bachata','salsa'],true)?(string)$_POST['dance_style']:'bachata';$division=(string)($_POST['division']??'novice');if($dance==='salsa'&&!in_array($division,['novice','intermediate','advanced'],true))throw new RuntimeException('Salsa currently supports Novice, Intermediate and Advanced only.');$mode=in_array((string)($_POST['scoring_mode']??''),['manual','automated'],true)?(string)$_POST['scoring_mode']:'manual';$type=in_array((string)($_POST['round_type']??''),['heats','final'],true)?(string)$_POST['round_type']:'heats';$eventId=(int)($_POST['event_id']??0);$new=trim((string)($_POST['new_event_name']??''));if($eventId){$q=$pdo->prepare('SELECT status FROM bdc_events WHERE id=:id');$q->execute(['id'=>$eventId]);$status=(string)$q->fetchColumn();if($status==='')throw new RuntimeException('Event not found.');if(in_array($status,['completed','published'],true))throw new RuntimeException('This event is already '.ucfirst($status).' and cannot be reused for a new scoring workflow. Open it from Completed Events for amendments.');}else{if($new==='')throw new RuntimeException('Select an event or enter a new event name.');$slug=strtolower(trim((string)preg_replace('/[^a-z0-9]+/i','-',$new),'-')).'-'.date('YmdHis');$pdo->prepare("INSERT INTO bdc_events(name,normalised_name,slug,event_date,status) VALUES(:n,LOWER(:n),:s,NULLIF(:d,''),'draft')")->execute(['n'=>$new,'s'=>$slug,'d'=>trim((string)($_POST['new_event_date']??''))]);$eventId=(int)$pdo->lastInsertId();}$q=$pdo->prepare("SELECT id FROM bdc_scoring_rounds WHERE event_id=:e AND dance_style=:dance AND division=:d AND round_type=:t AND scoring_mode=:m AND status<>'archived' LIMIT 1");$q->execute(['e'=>$eventId,'dance'=>$dance,'d'=>$division,'t'=>$type,'m'=>$mode]);$roundId=(int)$q->fetchColumn();if(!$roundId){$pdo->prepare("INSERT INTO bdc_scoring_rounds(event_id,dance_style,round_type,scoring_mode,division,yes_count,callback_count,yes_weight,alt1_weight,alt2_weight,alt3_weight,created_by) VALUES(:e,:dance,:t,:m,:d,10,10,10,4.5,4.3,4.2,:u)")->execute(['e'=>$eventId,'dance'=>$dance,'t'=>$type,'m'=>$mode,'d'=>$division,'u'=>$userId?:null]);$roundId=(int)$pdo->lastInsertId();auditD($pdo,$roundId,$userId,'round_created',['dance_style'=>$dance]);}header('Location: index.php?mode='.$mode.'&round_id='.$roundId,true,303);exit;}if($action==='create_next_round'){throw new RuntimeException('Use the existing round workflow to advance this competition.');}if($action==='delete_scoring_workflow'){$eventId=(int)($_POST['event_id']??0);$q=$pdo->prepare('SELECT status FROM bdc_events WHERE id=:id');$q->execute(['id'=>$eventId]);if(in_array((string)$q->fetchColumn(),['completed','published'],true))throw new RuntimeException('Published or completed scoring cannot be deleted.');throw new RuntimeException('Destructive workflow deletion is restricted to Scoring Tests Dashboard.');}throw new RuntimeException('Unsupported action.');}catch(Throwable $e){$_SESSION['scoring_error']=$e->getMessage();header('Location: index.php?mode='.rawurlencode((string)($_POST['scoring_mode']??'manual')),true,303);exit;}